import { test, expect } from 'vitest';
import GBNF, { RuleType, RuleChar, isRange, ParseState, InputParseError } from 'gbnf';

test('smoke: printing + misc api', () => {
  const state = GBNF('root ::= [a-z] "\\n" | foo\nfoo ::= "foo"');
  expect(state).toBeInstanceOf(ParseState);
  expect(state.size).toBe(2);
  expect(state.grammar).toContain('root');
  expect(String(state)).toContain('char');
  // reach into the graph for the debug printers
  const graph = (state as any).graph;
  expect(graph.print(undefined, false)).toContain('[a-z]'.slice(0, 1));
  expect(graph.print((state as any).pointers, true)).toBeTruthy();
  expect(String(graph)).toBeTruthy();
  const node = [...graph.roots.get(0).values()][0];
  expect(String(node)).toBeTruthy();
  expect(String([...(state as any).pointers][0])).toBeTruthy();
  expect(RuleType.CHAR).toBe('char');
  expect(isRange([1, 2])).toBe(true);
  expect(isRange([1, 2, 3])).toBe(false);
  expect(new RuleChar([1, [2, 3]]).value).toEqual([1, [2, 3]]);
  const err = new InputParseError('z', 0, 'ba');
  expect(err.src).toBe('baz');
  expect(err.errorForMostRecentInput).toContain('Failed to parse input string:');
  expect(err instanceof InputParseError).toBe(true);
  expect(err instanceof Error).toBe(true);
  // code point array + number inputs
  expect([...GBNF('root ::= "foo"', [102, 111])]).toEqual([{ type: 'char', value: [111] }]);
  expect([...GBNF('root ::= "foo"').add(102)]).toEqual([{ type: 'char', value: [111] }]);
});
